CREATE TABLE IF NOT EXISTS astra_schema_version(version INTEGER NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_profiles(identity_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,bot_key VARCHAR(256) NOT NULL,entity_type VARCHAR(32) NOT NULL,identity_json LONGTEXT NOT NULL,fields_json LONGTEXT NOT NULL,display_name VARCHAR(512) NOT NULL,source VARCHAR(128) NOT NULL,first_seen BIGINT NOT NULL,last_seen BIGINT NOT NULL,complete_flag INTEGER NOT NULL,INDEX astra_profile_scope(bot_key,entity_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_members(relation_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,chat_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,member_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,active_flag INTEGER NOT NULL,last_seen BIGINT NOT NULL,fields_json LONGTEXT NOT NULL,source VARCHAR(256) NOT NULL,chat_json LONGTEXT NOT NULL,member_json LONGTEXT NOT NULL,INDEX astra_member_chat(chat_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_union_links(identity_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,scope_name VARCHAR(256) NOT NULL,entity_type VARCHAR(32) NOT NULL,union_id VARCHAR(256) NOT NULL,INDEX astra_union_scope(scope_name,entity_type,union_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_metadata(plugin_id VARCHAR(128) NOT NULL,identity_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,fields_json LONGTEXT NOT NULL,PRIMARY KEY(plugin_id,identity_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_events(event_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,chat_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,state VARCHAR(32) NOT NULL,created_at BIGINT NOT NULL,INDEX astra_events_age(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_handlers(event_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,handler_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,plugin_id VARCHAR(128) NOT NULL,position INTEGER NOT NULL,state VARCHAR(32) NOT NULL,error_text LONGTEXT NOT NULL,PRIMARY KEY(event_key,handler_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_history(record_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,event_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,bot_key VARCHAR(256) NOT NULL,chat_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,chat_json LONGTEXT NOT NULL,actor_key VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin,actor_json LONGTEXT,message_id VARCHAR(512) NOT NULL,message_index VARCHAR(512) NOT NULL,message_json LONGTEXT NOT NULL,occurred_at BIGINT NOT NULL,outgoing_flag INTEGER NOT NULL,recalled_flag INTEGER NOT NULL,recalled_at BIGINT,processing_state VARCHAR(32) NOT NULL,INDEX astra_history_chat(chat_key,occurred_at),INDEX astra_history_event(event_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_plugin_state(plugin_id VARCHAR(128) NOT NULL,bot_key VARCHAR(256) NOT NULL,enabled_flag INTEGER NOT NULL,PRIMARY KEY(plugin_id,bot_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS astra_outbound(job_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,bot_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,plugin_id VARCHAR(128) NOT NULL,state VARCHAR(32) NOT NULL,result_json LONGTEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS astra_reply_sequences(reply_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,next_seq INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS astra_gateway(gateway_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,session_id VARCHAR(256) NOT NULL,accepted_seq BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS astra_runtime_lock(lock_id INTEGER PRIMARY KEY,owner_id VARCHAR(64) NOT NULL,expires_at BIGINT NOT NULL);
